const q = $input.first().json.query || {};
const mode = q["hub.mode"];
const token = q["hub.verify_token"];
const challenge = q["hub.challenge"];

const VERIFY_TOKEN = "SEU_TOKEN_AQUI"; // você inventa e coloca igual na Meta

if (mode === "subscribe" && token === VERIFY_TOKEN && challenge) {
  return [{ status: 200, body: challenge }];
}

return [{ status: 403, body: "Forbidden" }];

// n8n Webhook node wraps Meta payload inside $json.body
const envelope = $input.first().json;
const body = envelope.body ?? envelope;

// Helpers
const first = (arr) => (Array.isArray(arr) && arr.length ? arr[0] : null);
const safe = (v, d = null) => (v === undefined ? d : v);

// Estrutura principal do payload da Meta
const entry = first(body.entry) || null;
const change = first(entry?.changes) || null;
const value = change?.value || body;

// Campos principais
const messaging_product = safe(value?.messaging_product);
const field = safe(change?.field || value?.field);

// Metadata
const metadata = value?.metadata || {};
const phone_number_id = safe(metadata?.phone_number_id);
const display_phone_number = safe(metadata?.display_phone_number);

// Arrays possíveis
const messages = Array.isArray(value?.messages) ? value.messages : [];
const statuses = Array.isArray(value?.statuses) ? value.statuses : [];
const calls = Array.isArray(value?.calls) ? value.calls : [];

// Contact
const contact = first(value?.contacts) || null;
const contact_wa_id = safe(contact?.wa_id);
const contact_name = safe(contact?.profile?.name);

// Output
const out = [];

// =========================
// MESSAGE EVENTS
// =========================
for (const msg of messages) {
  const buttonReplyId = safe(msg?.interactive?.button_reply?.id);
  const buttonReplyTitle = safe(msg?.interactive?.button_reply?.title);

  out.push({
    received_at: new Date().toISOString(),
    event_type: "message",

    messaging_product,
    field,
    phone_number_id,
    display_phone_number,

    wa_id: contact_wa_id || safe(msg?.from),
    from_number: safe(msg?.from),
    contact_name,

    message_id: safe(msg?.id),
    message_type: safe(msg?.type),
    text_body: safe(msg?.text?.body),

    button_reply_id: buttonReplyId,
    button_reply_title: buttonReplyTitle,

    // Campos de status
    status_message_id: null,
    status_value: null,
    status_timestamp: safe(msg?.timestamp),
    status_recipient_id: null,

    // Campos legados compatíveis
    status: null,
    recipient_id: null,
    timestamp_meta: safe(msg?.timestamp),

    // Pricing
    pricing_billable: null,
    pricing_model: null,
    pricing_category: null,
    pricing_type: null,

    // Errors
    error_code: null,
    error_title: null,
    error_message: null,

    // Calls
    call_id: null,
    call_event: null,
    call_timestamp: null,
    call_from_number: null,
    call_direction: null,
    call_duration: null,
    call_reason: null,

    raw_payload: body,
  });
}

// =========================
// STATUS EVENTS
// =========================
for (const st of statuses) {
  const pricing = st?.pricing || null;
  const err = Array.isArray(st?.errors) && st.errors.length ? st.errors[0] : null;

  out.push({
    received_at: new Date().toISOString(),
    event_type: "status",

    messaging_product,
    field,
    phone_number_id,
    display_phone_number,

    wa_id: null,
    from_number: null,
    contact_name: null,

    message_id: null,
    message_type: null,
    text_body: null,

    button_reply_id: null,
    button_reply_title: null,

    // Campos novos
    status_message_id: safe(st?.id),
    status_value: safe(st?.status),
    status_timestamp: safe(st?.timestamp),
    status_recipient_id: safe(st?.recipient_id),

    // Campos legados
    status: safe(st?.status),
    recipient_id: safe(st?.recipient_id),
    timestamp_meta: safe(st?.timestamp),

    // Pricing
    pricing_billable: safe(pricing?.billable),
    pricing_model: safe(pricing?.pricing_model),
    pricing_category: safe(pricing?.category),
    pricing_type: safe(pricing?.type),

    // Errors
    error_code: safe(err?.code),
    error_title: safe(err?.title),
    error_message: safe(err?.message),

    // Calls
    call_id: null,
    call_event: null,
    call_timestamp: null,
    call_from_number: null,
    call_direction: null,
    call_duration: null,
    call_reason: null,

    raw_payload: body,
  });
}

// =========================
// CALL EVENTS
// =========================
for (const c of calls) {
  const fromNum =
    safe(c?.from) ??
    safe(c?.caller) ??
    safe(c?.phone_number) ??
    safe(c?.source) ??
    null;

  const callEvent =
    safe(c?.event) ??
    safe(c?.status) ??
    safe(c?.type) ??
    null;

  out.push({
    received_at: new Date().toISOString(),
    event_type: "call",

    messaging_product,
    field,
    phone_number_id,
    display_phone_number,

    wa_id: contact_wa_id || fromNum,
    from_number: fromNum,
    contact_name,

    message_id: null,
    message_type: null,
    text_body: null,

    button_reply_id: null,
    button_reply_title: null,

    // Campos de status
    status_message_id: null,
    status_value: null,
    status_timestamp: null,
    status_recipient_id: null,

    // Campos legados
    status: null,
    recipient_id: null,
    timestamp_meta: null,

    // Pricing
    pricing_billable: null,
    pricing_model: null,
    pricing_category: null,
    pricing_type: null,

    // Errors
    error_code: null,
    error_title: null,
    error_message: null,

    // Calls
    call_id: safe(c?.id),
    call_event: callEvent,
    call_timestamp: safe(c?.timestamp),
    call_from_number: fromNum,
    call_direction: safe(c?.direction),
    call_duration: safe(c?.duration),
    call_reason: safe(c?.reason),

    raw_payload: body,
  });
}

// =========================
// FALLBACK
// =========================
if (out.length === 0) {
  out.push({
    received_at: new Date().toISOString(),
    event_type: "unknown",

    messaging_product,
    field,
    phone_number_id,
    display_phone_number,

    wa_id: contact_wa_id,
    from_number: null,
    contact_name,

    message_id: null,
    message_type: null,
    text_body: null,

    button_reply_id: null,
    button_reply_title: null,

    // Campos de status
    status_message_id: null,
    status_value: null,
    status_timestamp: null,
    status_recipient_id: null,

    // Campos legados
    status: null,
    recipient_id: null,
    timestamp_meta: null,

    // Pricing
    pricing_billable: null,
    pricing_model: null,
    pricing_category: null,
    pricing_type: null,

    // Errors
    error_code: null,
    error_title: null,
    error_message: null,

    // Calls
    call_id: null,
    call_event: null,
    call_timestamp: null,
    call_from_number: null,
    call_direction: null,
    call_duration: null,
    call_reason: null,

    raw_payload: body,
  });
}

return out;

