const statsRows = $input.all(0).map(i => i.json);
const convRows  = $input.all(1).map(i => i.json);

const d = new Date(Date.now() - 24 * 3600 * 1000);
const dayLabel = `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}/${d.getFullYear()}`;

const byCat = new Map();

for (const s of statsRows) {
  const cat = String(s.category ?? "unknown");
  byCat.set(cat, {
    category: cat,
    sent: Number(s.sent || 0),
    delivered: Number(s.delivered || 0),
    read: Number(s.read || 0),
    failed: Number(s.failed || 0),
    unique_recipients: Number(s.unique_recipients || 0),
    unique_conversions: 0,
    revenue: 0
  });
}

for (const c of convRows) {
  const cat = String(c.category ?? "unknown");
  const cur = byCat.get(cat) || {
    category: cat,
    sent: 0,
    delivered: 0,
    read: 0,
    failed: 0,
    unique_recipients: 0,
    unique_conversions: 0,
    revenue: 0
  };

  cur.unique_conversions = Number(c.unique_conversions || 0);
  cur.revenue = Number(c.revenue || 0);

  byCat.set(cat, cur);
}

const cats = Array.from(byCat.keys()).sort((a, b) => a.localeCompare(b));

const pct = (x) => Number(x || 0).toFixed(1);
const brl = (v) => {
  const n = Number(v || 0);
  const s = n.toFixed(2);
  const [i, dec] = s.split(".");
  const withDots = i.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return `R$ ${withDots},${dec}`;
};

let totalSent = 0;
let totalDelivered = 0;
let totalRead = 0;
let totalFailed = 0;
let totalUniqueRecipients = 0;
let totalConversions = 0;
let totalRevenue = 0;

let lines = [];
lines.push(`📊 **Mr. Teddy | Relatório Diário WhatsApp**`);
lines.push(`Período: **${dayLabel}**`);
lines.push(`Regra de atribuição: último **DELIVERED** do mesmo telefone normalizado até **6h** antes do pedido`);
lines.push(``);

for (const cat of cats) {
  const r = byCat.get(cat);
  const readRate = r.delivered > 0 ? (r.read / r.delivered) * 100 : 0;
  const convRate = r.delivered > 0 ? (r.unique_conversions / r.delivered) * 100 : 0;

  totalSent += r.sent;
  totalDelivered += r.delivered;
  totalRead += r.read;
  totalFailed += r.failed;
  totalUniqueRecipients += r.unique_recipients;
  totalConversions += r.unique_conversions;
  totalRevenue += r.revenue;

  lines.push(`**${cat.toUpperCase()}**`);
  lines.push(`• Sent: ${r.sent}`);
  lines.push(`• Delivered: ${r.delivered}`);
  lines.push(`• Read: ${r.read} (${pct(readRate)}%)`);
  lines.push(`• Failed: ${r.failed}`);
  lines.push(`• Clientes únicos impactados: ${r.unique_recipients}`);
  lines.push(`• Clientes que compraram: ${r.unique_conversions} (${pct(convRate)}%)`);
  lines.push(`• Receita atribuída: ${brl(r.revenue)}`);
  lines.push(``);
}

const totalReadRate = totalDelivered > 0 ? (totalRead / totalDelivered) * 100 : 0;
const totalConvRate = totalDelivered > 0 ? (totalConversions / totalDelivered) * 100 : 0;

lines.push(`**TOTAL**`);
lines.push(`• Sent: ${totalSent}`);
lines.push(`• Delivered: ${totalDelivered}`);
lines.push(`• Read: ${totalRead} (${pct(totalReadRate)}%)`);
lines.push(`• Failed: ${totalFailed}`);
lines.push(`• Clientes únicos impactados: ${totalUniqueRecipients}`);
lines.push(`• Clientes que compraram: ${totalConversions} (${pct(totalConvRate)}%)`);
lines.push(`• Receita atribuída: ${brl(totalRevenue)}`);

return [{ text_to_send: lines.join('\n') }];

